<?php
declare(strict_types=1);
class CertificateTypefaceException extends RuntimeException{}
function certificate_pdf(array $record,bool $sample=false):string{
 require_once __DIR__.'/certificate-pdf/vendor/autoload.php';
 foreach(['iconv','gzcompress','mb_strlen','mb_substr','mb_convert_encoding'] as $function)if(!function_exists($function))throw new RuntimeException('Certificate rendering prerequisite unavailable.');
 $cache=__DIR__.'/certificate-font-cache';if(!is_dir($cache.'/unifont')&&!mkdir($cache.'/unifont',0700,true)&&!is_dir($cache.'/unifont'))throw new RuntimeException('Certificate font cache unavailable.');
 if(!defined('FPDF_FONTPATH'))define('FPDF_FONTPATH',$cache.'/');
 if(!defined('_SYSTEM_TTFONTS'))define('_SYSTEM_TTFONTS',__DIR__.'/certificate-pdf/vendor/setasign/tfpdf/font/unifont/');
 $lock=fopen($cache.'/render.lock','c');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('Certificate rendering is busy.');
 try{
  $name=preg_replace('/\s+/u',' ',trim($record['student_name']));
  if(!preg_match("/^[\\p{Latin}\\p{M}\\p{N}\\p{Zs}'’.,()&\\-]+$/u",$name))throw new CertificateTypefaceException('This name needs the printable certificate view to preserve its script.');
  $metrics=new TTFontFile();$metrics->getMetrics(_SYSTEM_TTFONTS.'DejaVuSerif.ttf');
  foreach(preg_split('//u',$name,-1,PREG_SPLIT_NO_EMPTY) as $char){$cp=unpack('N',mb_convert_encoding($char,'UTF-32BE','UTF-8'))[1];if($cp>65535||!isset($metrics->charWidths[$cp*2+1])||(ord($metrics->charWidths[$cp*2])===0&&ord($metrics->charWidths[$cp*2+1])===0))throw new CertificateTypefaceException('This name needs the printable certificate view to preserve its characters.');}unset($metrics);
  $pdf=new tFPDF('L','mm','A4');$pdf->SetAutoPageBreak(false);$pdf->SetMargins(20,15,20);$pdf->SetCompression(true);
  $pdf->AddFont('SomaSans','','DejaVuSans.ttf',true);$pdf->AddFont('SomaSerif','','DejaVuSerif.ttf',true);$pdf->AddFont('SomaSerif','I','DejaVuSerif-Italic.ttf',true);
  $pdf->SetTitle($sample?'Sample completion certificate':$record['certificate_number'].' - Certificate of Completion',true);$pdf->SetAuthor('Soma na Mbiti',true);$pdf->SetCreator('Soma na Mbiti classroom',true);$pdf->AddPage();
  $pdf->SetFillColor(248,244,233);$pdf->Rect(0,0,297,210,'F');$pdf->SetDrawColor(48,75,60);$pdf->SetLineWidth(.45);$pdf->Rect(10,10,277,190);$pdf->SetDrawColor(190,178,145);$pdf->SetLineWidth(.18);$pdf->Rect(13,13,271,184);
  $pdf->SetFillColor(48,75,60);$pdf->Rect(22,21,13,14,'F');$pdf->SetTextColor(250,246,235);$pdf->SetFont('SomaSerif','I',25);$pdf->SetXY(22,21);$pdf->Cell(13,12,'m.',0,0,'C');
  $pdf->SetTextColor(39,45,39);$pdf->SetFont('SomaSerif','',18);$pdf->SetXY(40,21);$pdf->Cell(150,8,'Soma na Mbiti');$pdf->SetFont('SomaSans','',6.7);$pdf->SetTextColor(100,107,94);$pdf->SetXY(40,30);$pdf->Cell(150,4,empty($record['standard_course'])?'THE INVESTING CLASSROOM':'THE SCHOOL FOR CURIOUS MINDS');
  $pdf->SetFont('SomaSans','',7);$pdf->SetXY(201,23);$pdf->Cell(73,5,$sample?'SAMPLE - NOT A COURSE AWARD':'ISSUED BY SOMA NA MBITI',0,1,'R');$pdf->SetXY(201,29);$pdf->Cell(73,4,'somanambiti.com',0,1,'R');
  $pdf->SetDrawColor(190,178,145);$pdf->Line(23,42,274,42);$pdf->SetTextColor(48,75,60);$pdf->SetFont('SomaSerif','',28);$pdf->SetXY(20,49);$pdf->Cell(257,13,'Certificate of Completion',0,1,'C');
  $pdf->SetTextColor(103,107,95);$pdf->SetFont('SomaSans','',8);$pdf->SetXY(20,69);$pdf->Cell(257,5,'AWARDED TO',0,1,'C');
  $size=30;$pdf->SetFont('SomaSerif','',$size);while($pdf->GetStringWidth($name)>244&&$size>18){$size--;$pdf->SetFont('SomaSerif','',$size);}$pdf->SetTextColor(39,45,39);$pdf->SetXY(26,79);$pdf->MultiCell(245,11,$name,0,'C');
  $pdf->SetDrawColor(173,156,116);$pdf->SetLineWidth(.2);$pdf->Line(111,108,186,108);$pdf->SetTextColor(99,105,91);$pdf->SetFont('SomaSans','',9.2);$pdf->SetXY(23,113);$pdf->Cell(251,7,empty($record['standard_course'])?'for completing four learning modules and passing the final course examination in':'for completing ten teaching weeks and passing the final course examination in',0,1,'C');
  $pdf->SetTextColor(48,75,60);$pdf->SetFont('SomaSerif','',21);$pdf->SetXY(21,124);$pdf->Cell(255,10,$record['course_title'],0,1,'C');
  $percent=number_format((int)$record['score']/(int)$record['maximum']*100,2);$pdf->SetTextColor(99,105,91);$pdf->SetFont('SomaSans','',8.5);$pdf->SetXY(22,139);$pdf->Cell(253,6,'Final examination: '.$record['score'].'/'.$record['maximum'].' ('.$percent.'%)   |   Required pass mark: 85%',0,1,'C');
  $signers=json_decode($record['signatories_json'],true,16,JSON_THROW_ON_ERROR);$width=241/count($signers);
  foreach($signers as $i=>$signer){$x=28+$i*$width;$font=18;$pdf->SetFont('SomaSerif','I',$font);while($pdf->GetStringWidth($signer['name'])>$width-12&&$font>10){$font--;$pdf->SetFont('SomaSerif','I',$font);}$pdf->SetTextColor(48,75,60);$pdf->SetXY($x,155);$pdf->Cell($width,10,$signer['name'],0,1,'C');$line=min(77,$width-12);$pdf->SetDrawColor(130,140,117);$pdf->Line($x+($width-$line)/2,168,$x+($width+$line)/2,168);$pdf->SetTextColor(99,105,91);$pdf->SetFont('SomaSans','',8);$pdf->SetXY($x,171);$pdf->MultiCell($width,4.5,$signer['title'],0,'C');$pdf->SetXY($x,178);$pdf->Cell($width,4,$signer['organisation'],0,1,'C');}
  $issued=(new DateTimeImmutable($record['issued_at']))->setTimezone(new DateTimeZone('Africa/Nairobi'))->format('j F Y');$pdf->SetDrawColor(190,178,145);$pdf->Line(23,186,274,186);$pdf->SetFont('SomaSans','',6.8);$pdf->SetTextColor(100,107,94);$pdf->SetXY(24,189);$pdf->Cell(95,4,'Certificate: '.$record['certificate_number'],0,0,'L');$pdf->Cell(70,4,'Student: '.$record['student_number'],0,0,'C');$pdf->Cell(84,4,'Issued: '.$issued,0,1,'R');$pdf->SetFont('SomaSans','',6.2);$pdf->SetXY(22,194);$pdf->Cell(253,3,'Educational course completion only. This certificate does not confer a professional licence or assure trading performance.',0,1,'C');
  return $pdf->Output('S');
 }finally{flock($lock,LOCK_UN);fclose($lock);}
}
function certificate_html(array $record,bool $sample=false):string{
 $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$signers=json_decode($record['signatories_json'],true,16,JSON_THROW_ON_ERROR);$date=(new DateTimeImmutable($record['issued_at']))->setTimezone(new DateTimeZone('Africa/Nairobi'))->format('j F Y');$nonce=bin2hex(random_bytes(16));
 header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-".$nonce."'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'");
 return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$e($record['certificate_number']).' - Soma na Mbiti</title><style>@page{size:A4 landscape;margin:0}*{box-sizing:border-box}body{margin:0;background:#e6e6dc;color:#272d27;font:16px Georgia,serif}.actions{max-width:1100px;margin:20px auto;display:flex;justify-content:space-between;gap:20px;font:14px Arial,sans-serif;padding:0 20px}.actions a{color:#304b3c}.actions button{background:#304b3c;color:white;border:0;padding:12px 20px;cursor:pointer;border-radius:4px}.certificate{background:#f8f4e9;width:1100px;max-width:calc(100% - 40px);margin:20px auto;padding:28px 46px;border:double 5px #819274;min-height:740px;text-align:center}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #beb291;padding-bottom:20px;text-align:left}.brand{font-size:28px}.top small{font:11px Arial,sans-serif;color:#646b5e}.sample{font:12px Arial,sans-serif;color:#865c3c}h1{font-weight:400;font-size:42px;color:#304b3c;margin:30px 0 24px}.eyebrow{font:10px Arial,sans-serif;letter-spacing:2px;color:#676b5f}.name{font-size:38px;line-height:1.5;margin:18px 0 25px;overflow-wrap:anywhere}.award p{font-size:16px;color:#63695b;line-height:1.8}.course{font-size:30px;color:#304b3c;margin:20px 0}.score{font:13px Arial,sans-serif;color:#63695b}.signatures{display:flex;justify-content:center;gap:30px;margin:34px 0 30px}.signer{flex:1;max-width:300px}.signer strong{font-size:25px;font-weight:400;font-style:italic;display:block;padding-bottom:12px;border-bottom:1px solid #828c75}.signer span{font:12px/1.8 Arial,sans-serif;display:block;margin-top:8px}.meta{display:flex;justify-content:space-between;gap:15px;font:10px/1.8 Arial,sans-serif;border-top:1px solid #beb291;padding-top:16px}.disclaimer{font:10px/1.9 Arial,sans-serif;color:#676b5f;margin-top:12px}@media(max-width:650px){.certificate{padding:25px;min-height:0}.top{display:block}.top small{display:block;margin-top:10px}h1{font-size:32px}.name{font-size:30px}.course{font-size:27px}.meta{flex-direction:column;gap:6px}.signatures{flex-wrap:wrap}.signer{min-width:170px}.actions{font-size:12px}.actions button{font-size:12px}}@media print{body{background:white}.actions{display:none}.certificate{width:297mm;max-width:none;min-height:210mm;margin:0;padding:10mm 15mm;border:double 1.5mm #819274;page-break-inside:avoid}h1{margin-top:8mm}.signatures{margin-top:10mm;margin-bottom:8mm}}</style><div class="actions"><a href="/#account">← My account</a><button type="button" id="print-certificate">Print / Save as PDF</button></div><main class="certificate"><div class="top"><div class="brand">Soma na Mbiti</div><small>'.$e($sample?'SAMPLE - NOT A COURSE AWARD':(empty($record['standard_course'])?'THE INVESTING CLASSROOM':'THE SCHOOL FOR CURIOUS MINDS')).'</small></div><h1>Certificate of Completion</h1><div class="eyebrow">AWARDED TO</div><div class="name" dir="auto">'.$e($record['student_name']).'</div><div class="award"><p>for completing '.(empty($record['standard_course'])?'four learning modules':'ten teaching weeks').' and passing the final course examination in</p><div class="course">'.$e($record['course_title']).'</div><div class="score">Final examination: '.$e($record['score']).'/'.$e($record['maximum']).' ('.number_format((int)$record['score']/(int)$record['maximum']*100,2).'%) · Required pass mark: 85%</div></div><div class="signatures">'.implode('',array_map(fn($s)=>'<div class="signer"><strong>'.$e($s['name']).'</strong><span>'.$e($s['title']).'<br>'.$e($s['organisation']).'</span></div>',$signers)).'</div><div class="meta"><span>Certificate: '.$e($record['certificate_number']).'</span><span>Student: '.$e($record['student_number']).'</span><span>Issued: '.$e($date).'</span></div><p class="disclaimer">Educational course completion only. This certificate does not confer a professional licence or assure trading performance.</p></main><script nonce="'.$nonce.'">document.getElementById("print-certificate").onclick=()=>window.print();</script></html>';
}
